const frame = context.panel.data.series && context.panel.data.series[0];
if (!frame) {
  context.grafana.notifyError(['Component Control', 'Component catalog is unavailable.']);
  return;
}

const values = (name) => {
  const field = frame.fields.find((item) => item.name === name);
  return field ? Array.from(field.values) : [];
};

const names = values('Component');
const eligible = values('Eligible');
const autonomous = values('Run autonomously');
const options = [];
const selected = [];

for (let i = 0; i < names.length; i += 1) {
  const name = String(names[i] || '').trim();
  if (!name || eligible[i] !== true) {
    continue;
  }
  options.push({ id: name, label: name, value: name });
  if (autonomous[i] === true) {
    selected.push(name);
  }
}

const helpers = (opts = []) => ({
  showIf: () => true,
  disableIf: () => false,
  getOptions: () => opts,
});

context.panel.onChangeElements([
  {
    uid: 'autonomous-components',
    id: 'autonomous_components',
    title: `Run autonomously (${selected.length} selected / ${options.length} eligible)`,
    type: 'checkboxList',
    optionsSource: 'Custom',
    options,
    allowCustomValue: false,
    value: selected,
    labelWidth: 20,
    section: '',
    tooltip: 'Checked components may be selected by Jason without a per-run technician approval. Ineligible components remain visible in the table above.',
    unit: '',
    helpers: helpers(options),
  },
  {
    uid: 'select-all-components', id: 'select_all_components', title: 'Select All', type: 'button',
    buttonLabel: 'Select All Eligible', show: 'form', size: 'md', variant: 'secondary',
    foregroundColor: '', backgroundColor: '', labelWidth: 10, section: '', tooltip: '', unit: '',
    customCode: `const target = context.panel.elements.find((e) => e.id === 'autonomous_components');\nif (!target) return;\nconst all = (target.options || []).map((o) => o.value);\ncontext.panel.onChangeElements(context.panel.elements.map((e) => e.id === 'autonomous_components' ? { ...e, value: all } : e));`,
    helpers: helpers(),
  },
  {
    uid: 'select-none-components', id: 'select_none_components', title: 'Select None', type: 'button',
    buttonLabel: 'Select None', show: 'form', size: 'md', variant: 'secondary',
    foregroundColor: '', backgroundColor: '', labelWidth: 10, section: '', tooltip: '', unit: '',
    customCode: `context.panel.onChangeElements(context.panel.elements.map((e) => e.id === 'autonomous_components' ? { ...e, value: [] } : e));`,
    helpers: helpers(),
  },
  {
    uid: 'refresh-components', id: 'refresh_components', title: 'Refresh', type: 'button',
    buttonLabel: 'Refresh', show: 'form', size: 'md', variant: 'secondary',
    foregroundColor: '', backgroundColor: '', labelWidth: 10, section: '', tooltip: '', unit: '',
    customCode: `context.grafana.locationService.reload();`,
    helpers: helpers(),
  },
  {
    uid: 'apply-components', id: 'apply_components', title: 'Apply', type: 'button',
    buttonLabel: 'Apply Autonomous Approvals', show: 'form', size: 'md', variant: 'primary',
    foregroundColor: '', backgroundColor: '', labelWidth: 10, section: '', tooltip: '', unit: '',
    customCode: `const target = context.panel.elements.find((e) => e.id === 'autonomous_components');\nconst selected = Array.isArray(target?.value) ? target.value : [];\nfetch('/api/datasources/proxy/uid/jason-component-control/component-control/components', { credentials: 'same-origin' })\n  .then((response) => { if (!response.ok) throw new Error('Unable to refresh current approvals'); return response.json(); })\n  .then((current) => {\n    const currentSet = new Set(current.autonomous_names || []);\n    const selectedSet = new Set(selected);\n    const approve = selected.filter((name) => !currentSet.has(name));\n    const revoke = Array.from(currentSet).filter((name) => !selectedSet.has(name));\n    if (!approve.length && !revoke.length) {\n      context.grafana.notifySuccess(['Component Control', 'No approval changes are required.']);\n      return null;\n    }\n    if (!window.confirm('Apply ' + approve.length + ' autonomous approvals and ' + revoke.length + ' revocations?')) return null;\n    return fetch('/api/datasources/proxy/uid/jason-component-control/component-control/bulk', {\n      method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ approve_names: approve, revoke_names: revoke, reason: 'Grafana Component Control' })\n    });\n  })\n  .then((response) => {\n    if (!response) return null;\n    return response.json().then((body) => ({ response, body }));\n  })\n  .then((result) => {\n    if (!result) return;\n    if (!result.response.ok) throw new Error(result.body?.error || 'Bulk approval update failed');\n    const b = result.body || {};\n    if (b.failed_count) {\n      context.grafana.notifyError(['Component Control', 'Partial result: ' + (b.approved_count || 0) + ' approved, ' + (b.revoked_count || 0) + ' revoked, ' + b.failed_count + ' failed.']);\n    } else {\n      context.grafana.notifySuccess(['Component Control', (b.approved_count || 0) + ' approved, ' + (b.revoked_count || 0) + ' revoked.']);\n    }\n    setTimeout(() => context.grafana.locationService.reload(), 600);\n  })\n  .catch((error) => context.grafana.notifyError(['Component Control', String(error.message || error)]));`,
    helpers: helpers(),
  },
]);
